package com.pratik.imagetap;
import org.junit.*;import static org.junit.Assert.*;import java.util.*;
/** Deterministic virtual-time tests: no sleeps and no claims about phone throughput. */
public class AutoTapRunner73Test {
 static final class Time implements AutoTapRunner.Scheduler {long now;int seq;static class Entry{Runnable r;long at;int seq;Entry(Runnable r,long at,int seq){this.r=r;this.at=at;this.seq=seq;}}List<Entry> queue=new ArrayList<>();public long now(){return now;}public void post(Runnable r,long delay){queue.add(new Entry(r,now+delay,seq++));}public void cancel(Runnable r){queue.removeIf(e->e.r==r);}void advance(long ms){long end=now+ms;int budget=100000;while(true){Entry e=queue.stream().filter(x->x.at<=end).min(Comparator.<Entry>comparingLong(x->x.at).thenComparingInt(x->x.seq)).orElse(null);if(e==null)break;if(--budget==0)throw new AssertionError("Infinite scheduling loop");queue.remove(e);now=e.at;e.r.run();}now=end;}}
 Time time;AutoTapPlan plan;AutoTapRunner r;AutoTapRunner.Result callback;List<Integer> sent;List<Integer> holds;boolean accept=true;String block;
 @Before public void setup(){time=new Time();plan=new AutoTapPlan();sent=new ArrayList<>();holds=new ArrayList<>();}
 void runner(){r=new AutoTapRunner(plan,time,(i,h,c)->{sent.add(i);holds.add(h);callback=c;return accept;},()->block,()->{});}
 @Test public void fastestHasOneMillisecondHoldAndNoAddedGap(){plan.hold=1;plan.gap=0;runner();r.play();time.advance(0);assertEquals(Arrays.asList(0),sent);assertEquals(Arrays.asList(1),holds);time.advance(50);assertEquals(1,sent.size());callback.finish(true);time.advance(0);assertEquals(2,sent.size());assertEquals(1,r.taps);}
 @Test public void noOverlappingGesturesEvenWhenIntervalIsZero(){plan.gap=0;runner();r.play();time.advance(0);r.play();time.advance(500);assertEquals(1,sent.size());assertTrue(r.pending);callback.finish(true);time.advance(0);assertEquals(2,sent.size());}
 @Test public void twoTargetsRunInOrderAndLimitCountsWholeCycles(){plan.count(2);plan.cycles=2;plan.gap=0;runner();r.play();time.advance(0);for(int i=0;i<4;i++){assertEquals(i%2,(int)sent.get(i));callback.finish(true);time.advance(0);}assertEquals(4,r.taps);assertEquals(2,r.cycles);assertTrue(r.done);assertFalse(r.playing);assertEquals(4,sent.size());}
 @Test public void twentyTargetsHaveCompleteCoverage(){plan.count(20);plan.cycles=1;plan.gap=0;runner();r.play();time.advance(0);for(int i=0;i<20;i++){assertEquals(i,(int)sent.get(i));callback.finish(true);time.advance(0);}assertTrue(r.done);assertEquals(20,new HashSet<>(sent).size());}
 @Test public void pendingCompletionWhilePausedCountsButNeverSchedulesNext(){plan.count(2);runner();r.play();time.advance(0);r.pause("Paused");callback.finish(true);time.advance(5000);assertEquals(1,sent.size());assertEquals(1,r.taps);assertEquals(1,r.index);r.play();time.advance(plan.gap-1);assertEquals(1,sent.size());time.advance(1);assertEquals(2,sent.size());assertEquals(1,(int)sent.get(1));}
 @Test public void pauseRetainsStartDelay(){plan.startDelay=3400;runner();r.play();time.advance(1000);r.pause("Paused");time.advance(20000);r.play();time.advance(2399);assertTrue(sent.isEmpty());time.advance(1);assertEquals(1,sent.size());}
 @Test public void pauseRetainsRemainingGap(){plan.gap=1200;runner();r.play();time.advance(0);callback.finish(true);time.advance(300);r.pause("Paused");time.advance(20000);r.play();time.advance(899);assertEquals(1,sent.size());time.advance(1);assertEquals(2,sent.size());}
 @Test public void stopInvalidatesLateCallbackAndQueuedTaps(){runner();r.play();time.advance(0);AutoTapRunner.Result old=callback;r.stop();old.finish(true);time.advance(10000);assertEquals(0,r.taps);assertEquals(1,sent.size());assertTrue(time.queue.isEmpty());r.play();time.advance(10000);assertEquals(1,sent.size());}
 @Test public void cancellationAndRejectionPauseWithoutAdvancing(){runner();r.play();time.advance(0);callback.finish(false);time.advance(1000);assertFalse(r.playing);assertEquals(0,r.index);assertEquals(0,r.taps);accept=false;r.play();time.advance(0);assertFalse(r.pending);assertFalse(r.playing);assertEquals(2,sent.size());assertEquals(0,r.taps);}
 @Test public void missingCallbackNeverBlindlyRetries(){runner();r.play();time.advance(0);time.advance(plan.hold+2000);assertFalse(r.playing);assertFalse(r.pending);assertTrue(r.message.contains("No completion"));callback.finish(true);assertEquals(0,r.taps);time.advance(60000);assertEquals(1,sent.size());}
 @Test public void perPointOverridesAreAppliedAfterEachCompletion(){plan.count(2);plan.points.get(0).hold=250;plan.points.get(0).gap=700;runner();r.play();time.advance(0);assertEquals(250,(int)holds.get(0));callback.finish(true);time.advance(699);assertEquals(1,sent.size());time.advance(1);assertEquals(2,sent.size());assertEquals(plan.hold,(int)holds.get(1));}
 @Test public void guardPreventsEveryDispatchIncludingAfterBackgroundChange(){runner();block="Screen locked";r.play();time.advance(0);assertTrue(sent.isEmpty());block=null;r.play();time.advance(0);callback.finish(true);block="Display rotated";time.advance(plan.gap);assertEquals(1,sent.size());assertFalse(r.playing);assertEquals(block,r.message);}
 @Test public void replayAfterLimitIsAnExplicitNewRun(){plan.cycles=1;runner();r.play();time.advance(0);callback.finish(true);assertTrue(r.done);r.play();time.advance(0);assertFalse(r.done);assertEquals(0,r.taps);assertEquals(2,sent.size());}
 @Test public void delayedCallbacksCannotDoubleCount(){runner();r.play();time.advance(0);AutoTapRunner.Result old=callback;old.finish(true);old.finish(true);assertEquals(1,r.taps);time.advance(plan.gap);old.finish(true);assertEquals(1,r.taps);assertTrue(r.pending);}
 @Test public void longSoakPreservesOrderAndHasBoundedQueue(){plan.count(20);plan.hold=1;plan.gap=0;runner();r.play();time.advance(0);for(int i=0;i<10000;i++){assertEquals(i%20,(int)sent.get(i));assertTrue(time.queue.size()<=1);callback.finish(true);time.advance(1);}assertEquals(10000,r.taps);assertEquals(500,r.cycles);r.stop();assertTrue(time.queue.isEmpty());}
 @Test public void illegalTimingAndCoordinatesAreRejected(){for(int hold:new int[]{0,-1,1001}){AutoTapPlan p=new AutoTapPlan();p.hold=hold;try{p.validate();fail();}catch(IllegalArgumentException expected){}}plan.points.get(0).x=Float.NaN;try{plan.validate();fail();}catch(IllegalArgumentException expected){}}
}
